args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?birthDate ?label WHERE {
  VALUES ?person { dbr:Patrik_Lácha dbr:Brad_Booth }
  OPTIONAL { ?person dbo:birthDate ?dboBirth . }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth . }
  BIND(coalesce(?dboBirth, ?dbpBirth) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
}
ORDER BY ?birthDate

